public sealed class Cmd:ICommand{readonly Func<Task> f;bool busy;public Cmd(Func<Task> x)=>f=x;public bool CanExecute(object? p)=>!busy;public async void Execute(object? p){busy=true;CanExecuteChanged?.Invoke(this,EventArgs.Empty);try{await f();}finally{busy=false;CanExecuteChanged?.Invoke(this,EventArgs.Empty);}}public event EventHandler? CanExecuteChanged;}
public sealed class MainViewModel:INotifyPropertyChanged{public event PropertyChangedEventHandler? PropertyChanged;void N([CallerMemberName]string? n=null)=>PropertyChanged?.Invoke(this,new(n));public string Target{get;set;}="127.0.0.1";public int Port{get;set;}=443;public int Count{get;set;}=4;public int Timeout{get;set;}=3000;string status="Ready",filter="";public string Status{get=>status;set{status=value;N();}}public string Filter{get=>filter;set{filter=value;N();PortView.Refresh();}}public ObservableCollection<PingRow> PingResults{get;}=new();public ObservableCollection<TcpRow> TcpResults{get;}=new();public ObservableCollection<string> TraceOutput{get;}=new();public ObservableCollection<PortRow> Ports{get;}=new();public ObservableCollection<Activity> History{get;}=new();public ICollectionView PortView{get;}CancellationTokenSource? cts;public ICommand Ping{get;}public ICommand Tcp{get;}public ICommand Trace{get;}public ICommand Stop{get;}public ICommand BulkPing{get;}public ICommand BulkTcp{get;}public ICommand ExportPing{get;}public ICommand ExportTcp{get;}public ICommand RefreshPorts{get;}public ICommand OpenLogs{get;}
public MainViewModel(){Directory.CreateDirectory(Path.Combine(AppContext.BaseDirectory,"Logs"));PortView=CollectionViewSource.GetDefaultView(Ports);PortView.Filter=o=>string.IsNullOrWhiteSpace(Filter)||o!.ToString()!.Contains(Filter,StringComparison.OrdinalIgnoreCase);Ping=new Cmd(RunPing);Tcp=new Cmd(RunTcp);Trace=new Cmd(RunTrace);BulkPing=new Cmd(()=>Bulk(false));BulkTcp=new Cmd(()=>Bulk(true));RefreshPorts=new Cmd(LoadPorts);Stop=new Cmd(()=>{cts?.Cancel();return Task.CompletedTask;});ExportPing=new Cmd(()=>Export(PingResults,"PingResults"));ExportTcp=new Cmd(()=>Export(TcpResults,"TCPResults"));OpenLogs=new Cmd(()=>{Process.Start(new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory,"Logs")){UseShellExecute=true});return Task.CompletedTask;});}
CancellationToken Token(){cts?.Cancel();cts=new();return cts.Token;}async Task RunPing(){var r=await DoPing("Single",Target,Token());PingResults.Insert(0,r);Add("PING",r.Target,r.Status,r.Avg,r.Error);}async Task<PingRow> DoPing(string name,string target,CancellationToken t){var s=DateTime.Now;string ip="",err="";var times=new List<long>();try{ip=(await Dns.GetHostAddressesAsync(target,t)).First().ToString();using var p=new Ping();for(int i=0;i<Count;i++){t.ThrowIfCancellationRequested();var x=await p.SendPingAsync(target,TimeSpan.FromMilliseconds(Timeout),new byte[32],new PingOptions(128,true),t);if(x.Status==IPStatus.Success)times.Add(x.RoundtripTime);else err=x.Status.ToString();}return new(name,target,ip,times.Count==Count?"SUCCESS":times.Count==0?"FAILED":"PARTIAL",Count,times.Count,100d*(Count-times.Count)/Count,times.Count>0?times.Min():null,times.Count>0?(long)times.Average():null,times.Count>0?times.Max():null,err,s,DateTime.Now);}catch(OperationCanceledException){return new(name,target,ip,"CANCELLED",Count,times.Count,0,null,null,null,"",s,DateTime.Now);}catch(Exception e){return new(name,target,ip,"FAILED",Count,0,100,null,null,null,e.Message,s,DateTime.Now);}}
async Task RunTcp(){var r=await DoTcp("Single",Target,Port,Token());TcpResults.Insert(0,r);Add("TCP",$"{r.Target}:{r.Port}",r.Status,r.Ms,r.Error);}async Task<TcpRow> DoTcp(string n,string host,int port,CancellationToken t){var s=DateTime.Now;string ip="";var sw=Stopwatch.StartNew();try{if(port is<1 or>65535)throw new ArgumentException("Port must be 1-65535");ip=(await Dns.GetHostAddressesAsync(host,t)).First().ToString();using var c=new TcpClient();using var l=CancellationTokenSource.CreateLinkedTokenSource(t);l.CancelAfter(Timeout);await c.ConnectAsync(host,port,l.Token);return new(n,host,port,ip,"OPEN",sw.ElapsedMilliseconds,"",s,DateTime.Now);}catch(OperationCanceledException){return new(n,host,port,ip,t.IsCancellationRequested?"CANCELLED":"TIMEOUT",null,"",s,DateTime.Now);}catch(SocketException e){return new(n,host,port,ip,e.SocketErrorCode==SocketError.ConnectionRefused?"CLOSED":"ERROR",null,e.Message,s,DateTime.Now);}catch(Exception e){return new(n,host,port,ip,"ERROR",null,e.Message,s,DateTime.Now);}}
async Task RunTrace(){TraceOutput.Clear();var t=Token();var p=new Process{StartInfo=new("tracert.exe",$"-d -h 30 -w {Timeout} \"{Target.Replace("\"","")}\""){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true}};try{p.Start();while(!p.StandardOutput.EndOfStream){t.ThrowIfCancellationRequested();TraceOutput.Add(await p.StandardOutput.ReadLineAsync(t)??"");}await p.WaitForExitAsync(t);Add("TRACE",Target,p.ExitCode==0?"SUCCESS":"FAILED",null,await p.StandardError.ReadToEndAsync());}catch(OperationCanceledException){try{p.Kill(true);}catch{}Add("TRACE",Target,"CANCELLED",null,"");}catch(Exception e){Add("TRACE",Target,"ERROR",null,e.Message);}finally{p.Dispose();}}
async Task Bulk(bool tcp){var d=new OpenFileDialog{Filter="CSV|*.csv"};if(d.ShowDialog()!=true)return;var rows=Csv.Read(d.FileName,tcp?new[]{"Name","Target","Port"}:new[]{"Name","Target"});var token=Token();using var gate=new SemaphoreSlim(10);var jobs=rows.Select(async r=>{await gate.WaitAsync(token);try{if(tcp){var x=await DoTcp(r["Name"],r["Target"],int.Parse(r["Port"]),token);App.Current.Dispatcher.Invoke(()=>TcpResults.Add(x));Add("TCP",$"{x.Target}:{x.Port}",x.Status,x.Ms,x.Error);}else{var x=await DoPing(r["Name"],r["Target"],token);App.Current.Dispatcher.Invoke(()=>PingResults.Add(x));Add("PING",x.Target,x.Status,x.Avg,x.Error);}}finally{gate.Release();}});try{await Task.WhenAll(jobs);}catch(OperationCanceledException){Status="CANCELLED";}}
Task Export<T>(IEnumerable<T> x,string name){var d=new SaveFileDialog{Filter="CSV|*.csv",FileName=$"{name}_{DateTime.Now:yyyyMMdd_HHmmss}.csv"};if(d.ShowDialog()==true)Csv.Write(d.FileName,x);return Task.CompletedTask;}void Add(string type,string target,string st,long? ms,string e){App.Current.Dispatcher.Invoke(()=>History.Insert(0,new(DateTime.Now,type,target,st,ms,e)));Status=st;try{File.AppendAllText(Path.Combine(AppContext.BaseDirectory,"Logs",$"Application_{DateTime.Now:yyyyMMdd}.log"),JsonSerializer.Serialize(new Activity(DateTime.Now,type,target,st,ms,e))+Environment.NewLine);}catch{}}
async Task LoadPorts(){Status="RUNNING";var x=await Task.Run(()=>PortApi.Read(Token()));Ports.Clear();foreach(var i in x)Ports.Add(i);Status=$"{x.Count} endpoints";}}
public static class Csv{static List<string>P(string s){var r=new List<string>();var b=new StringBuilder();bool q=false;for(int i=0;i<s.Length;i++){var c=s[i];if(c=='\"'){if(q&&i+1<s.Length&&s[i+1]=='\"'){b.Append('\"');i++;}else q=!q;}else if(c==','&&!q){r.Add(b.ToString().Trim());b.Clear();}else b.Append(c);}if(q)throw new InvalidDataException("Unclosed quote");r.Add(b.ToString().Trim());return r;}public static List<Dictionary<string,string>>Read(string f,string[] req){var l=File.ReadAllLines(f,Encoding.UTF8).Where(x=>!string.IsNullOrWhiteSpace(x)).ToList();if(l.Count==0)throw new InvalidDataException("Empty CSV");var h=P(l[0]);foreach(var x in req)if(!h.Contains(x,StringComparer.OrdinalIgnoreCase))throw new InvalidDataException("Missing column: "+x);return l.Skip(1).Select(P).Where(v=>v.Count==h.Count).Select(v=>h.Select((x,i)=>(x,v[i])).ToDictionary(a=>a.x,a=>a.Item2,StringComparer.OrdinalIgnoreCase)).DistinctBy(x=>string.Join('|',x.Values)).ToList();}public static void Write<T>(string f,IEnumerable<T> rows){var p=typeof(T).GetProperties().Where(x=>x.PropertyType.IsPrimitive||x.PropertyType==typeof(string)||x.PropertyType==typeof(DateTime)||Nullable.GetUnderlyingType(x.PropertyType)!=null).ToArray();using var w=new StreamWriter(f,false,new UTF8Encoding(true));w.WriteLine(string.Join(',',p.Select(x=>Q(x.Name))));foreach(var r in rows)w.WriteLine(string.Join(',',p.Select(x=>Q(Convert.ToString(x.GetValue(r))??""))));}static string Q(string s)=>$"\"{s.Replace("\"","\"\"")}\"";}
public static class PortApi{[DllImport("iphlpapi.dll")]static extern uint GetExtendedTcpTable(IntPtr p,ref int n,bool sort,int af,int c,uint r);[StructLayout(LayoutKind.Sequential)]struct Row{public uint State,LA,LP,RA,RP,Pid;}public static List<PortRow>Read(CancellationToken t){int n=0;GetExtendedTcpTable(IntPtr.Zero,ref n,true,2,5,0);var p=Marshal.AllocHGlobal(n);var o=new List<PortRow>();try{if(GetExtendedTcpTable(p,ref n,true,2,5,0)!=0)return o;int c=Marshal.ReadInt32(p);var x=IntPtr.Add(p,4);for(int i=0;i<c;i++){t.ThrowIfCancellationRequested();var r=Marshal.PtrToStructure<Row>(x);var pr=Proc((int)r.Pid);o.Add(new("TCP",new IPAddress(r.LA).ToString(),Pt(r.LP),new IPAddress(r.RA).ToString(),Pt(r.RP),r.State==2?"LISTENING":r.State==5?"ESTABLISHED":r.State.ToString(),(int)r.Pid,pr.Item1,pr.Item2));x=IntPtr.Add(x,Marshal.SizeOf<Row>());}return o;}finally{Marshal.FreeHGlobal(p);}}static int Pt(uint x)=>IPAddress.NetworkToHostOrder((short)(x&65535))&65535;static(string,string)Proc(int id){try{using var p=Process.GetProcessById(id);try{return(p.ProcessName,p.MainModule?.FileName??"");}catch{return(p.ProcessName,"Access Denied");}}catch{return("Process ended","");}}}